struct PresentationBridge {
 G2NaturalDriver& r;sf::Font font;std::unique_ptr<CombatPresentation> current,candidate;std::vector<PresentationEvent> pending;
 PresentationBridge(G2NaturalDriver& run):r(run){const auto& c=r.game.content();need(font.openFromFile(c.maps.begin()->second.fontPath),"08 actual font missing");current=std::make_unique<CombatPresentation>(c,font);r.game.configureRestorePresentation([&](const SceneDefinition&,const SavedPresentation& saved){candidate=std::make_unique<CombatPresentation>(r.game.content(),font);candidate->prepareRestoredState(saved);});r.observe=[&](const auto& e){pending.push_back(e);};r.afterTick=[&]{if(candidate){current=std::move(candidate);current->activateRestoredState();}current->update(pending);pending.clear();r.game.setPresentationState(current->saveState());};}
};
void summary(G2NaturalDriver& r,const std::filesystem::path& root){
 const auto& s=r.game.session();const auto e=s.exportState();Json j{{"steps",r.ticks},{"map",r.game.mapId()},{"hp",s.hp()},{"save_count",s.saveCount()},{"continue_count",s.variable(630)},{"kills",s.variable(35)},{"spray_uses",s.variable(382)},{"inventory",e.inventory},{"magazines",e.magazines},{"world_flags",e.worldFlags},{"world_values",e.worldValues},{"conditions",{{"poisoned",e.conditions.poisoned},{"bleeding",e.conditions.bleedingActive},{"corroded",e.conditions.corroded}}}};
 std::ofstream(root/"summary.json")<<j.dump(2)<<'\n';std::cout<<"08 steps="<<r.ticks<<" map="<<r.game.mapId()<<" HP="<<s.hp()<<" save="<<s.saveCount()<<" Continue="<<s.variable(630)<<" I20="<<s.magazine(20)<<" I21="<<s.magazine(21)<<'\n';
}
bool durableEqual(const SessionEntry& a,const SessionEntry& b){return a.inventory==b.inventory&&a.magazines==b.magazines&&a.itemUses==b.itemUses&&a.worldFlags==b.worldFlags&&a.worldValues==b.worldValues&&a.conditions==b.conditions&&a.hp==b.hp&&a.saveCount==b.saveCount&&a.eventTimer==b.eventTimer;}
void replay(G2NaturalDriver& r,const char* path,int limit){
 std::ifstream in(path);need(in.is_open(),"Missing verified public trace");std::string line;int count=0;
 while(std::getline(in,line)&&(limit==0||count<limit)){const auto j=Json::parse(line);need(j.at("map")== (r.game.hasGame()?r.game.mapId():0),"Public trace diverged at "+std::to_string(count)+" expected map="+std::to_string(int(j.at("map")))+" actual="+std::to_string(r.game.hasGame()?r.game.mapId():0));InputFrame f;int movement=j.at("movement"),held=j.at("held"),pressed=j.at("pressed");if(movement>=0){f.movement=Direction(movement);}for(std::size_t n=0;n<f.buttons.size();++n){f.buttons[n].held=held&(1<<n);f.buttons[n].pressed=pressed&(1<<n);}r.tick(f);++count;}
 need(limit==0||count==limit,"Trace shorter than selected successful prefix");std::cout<<"08 replay steps="<<count<<'\n';
}
void grabbed(G2NaturalDriver& r,bool success){
 auto& g=r.game;r.load();north(r);r.actObject("m169-e21");need(g.mapId()==166&&!g.session().flag(400),"08 real live Chimera missing");const auto id="m166-e5";r.lower();
 for(int n=0;n<6000&&!g.session().flag(10);++n){need(g.session().hp()>0&&g.mode()==ApplicationMode::Playing,"08 natural grab approach died");InputFrame in;const auto p=g.world().player().motion.tile(),t=findCharacter(g.world(),id).motion.tile();if(g.foreground()!=ForegroundKind::None||g.dialogue().active()){if(n%8==0){in=key();}}else if(!g.world().player().motion.moving()){bool adjacent=false;for(auto side:{Direction::Down,Direction::Left,Direction::Right,Direction::Up}){const auto goal=adjacentTile(t,side);if(p==goal){adjacent=true;break;}if(auto step=next(g.world(),goal)){in.movement=step;break;}}if(adjacent){in={};}}
 if(n%500==0){std::cout<<"08 grab approach n="<<n<<" p="<<p.x<<","<<p.y<<" e="<<t.x<<","<<t.y<<" hp="<<g.session().hp()<<" state="<<g.session().variable(91)<<" S13="<<g.session().flag(13)<<'\n';}r.tick(in);}
 const auto grabbedStates=g.enemyStates();need(g.session().flag(10)&&std::any_of(grabbedStates.begin(),grabbedStates.end(),[](const auto& v){return v.id=="m166-e5"&&v.holdsPlayer;}),"08 public approach never reached source grab");const int hp=g.session().hp();
 if(success){for(int n=0;n<1000&&(g.session().flag(10)||!g.session().flag(1));++n){r.tick(n%2==0?key(InputAction::Up):InputFrame{});}need(!g.session().flag(10)&&g.session().flag(1)&&g.session().variable(29)==0&&g.session().hp()==hp,"08 natural grab escape/CE10 did not recover");r.settle();r.equip(21);stageFight(r,id);for(const auto& door:{"m166-e15","m186-e5","m173-e2","m170-e5","m166-e19","m164-e3"}){r.actObject(door);}r.receptionBack();r.monitor(2);std::cout<<"08 natural grab/escape/CE10/ordinarySave PASS hp="<<hp<<'\n';}
 else{bool fatalPage=false;for(int n=0;n<3000&&g.mode()==ApplicationMode::Playing;++n){need(g.session().hp()==hp&&hp>0,"08 no-input grab changed positive HP");const auto states=g.enemyStates();fatalPage|=std::any_of(states.begin(),states.end(),[](const auto& v){return v.id=="m166-e5"&&(v.sourceState==5||v.sourceState==6);});r.tick(n%8==0&&g.dialogue().active()?key():InputFrame{});}std::cout<<"08 fatal outcome mode="<<int(g.mode())<<" fatal-page="<<fatalPage<<'\n';need(g.mode()==ApplicationMode::Title&&fatalPage,"08 no-input source P18/19 did not fail at positive HP");r.load();need(g.session().hp()>0&&!g.session().flag(10)&&g.session().variable(29)==0,"08 CE38 independent legal disk Load retained grab");std::cout<<"08 natural no-input P18/19 positiveHP failure/CE38/legal disk Load PASS hp="<<hp<<'\n';}
}
void boundary(G2NaturalDriver& r){auto& g=r.game;r.load();need(g.session().flag(510)&&g.session().flag(511)&&g.session().flag(462)&&g.session().count(111)==1&&!g.session().flag(530),"08 four-area source not ready");const auto before=g.session().exportState();r.reception();const auto* page=g.content().activeVariant(g.content().objects.at("m159-e6"),g.session());need(page&&page->page==3,"08 four-area door condition not active");r.actObject("m159-e6");need(g.mapId()==159&&!g.session().flag(530),"08 manufactured M190 or S530");const auto after=g.session().exportState();need(after.hp==before.hp&&after.inventory==before.inventory&&after.magazines==before.magazines&&after.worldFlags==before.worldFlags&&after.worldValues==before.worldValues,"08 unavailable M190 changed resources/facts");r.receptionBack();std::cout<<"08 actual M159511+I111 gate/refused unimplementedM190/unchanged resources PASS\n";}
void loadBatch(const CombatContent& c,const std::filesystem::path& root,const char* config){
 for(const auto& row:Json::parse(read(config))){const auto folder=root/row.at("name").get<std::string>();std::filesystem::create_directories(folder);const auto raw=read(row.at("source").get<std::string>().c_str());const auto disk=decodeSave(c,raw);std::ofstream(folder/"slot-01.json")<<raw;G2NaturalDriver r(c,folder,"public-inputs.jsonl");r.game.configureSaveDirectory(folder);PresentationBridge presentation(r);r.load();need(durableEqual(prepareRestore(c,disk).session->exportState(),r.game.session().exportState()),"08 independent public Load changed durable state");if(row.value("boundary",false)){boundary(r);}summary(r,folder);std::cout<<"08 independent process public Load PASS source="<<row.at("source")<<'\n';}
}
void plan(const CombatContent& c,const std::filesystem::path& root,const char* config){
 const auto stages=Json::parse(read(config));std::filesystem::path source=stages.at("source");
 for(const auto& row:stages.at("stages")){
  const auto folder=root/row.at("name").get<std::string>();std::filesystem::create_directories(folder);const auto raw=read(source.c_str());const auto saved=decodeSave(c,raw);std::ofstream(folder/"slot-01.json")<<raw;if(row.value("seed_slot2",false)){std::ofstream(folder/"slot-02.json")<<raw;}const std::string mode=row.at("mode");
  G2NaturalDriver r(c,folder,"public-inputs.jsonl",[&](int low,int high){if(mode=="replay03"&&low==1&&high==2){return 1;}if(mode=="replay04"&&low==0&&high==400){return 0;}if(mode=="replay04"&&low==0&&high==10){return 6;}return safe(low,high);});r.game.configureSaveDirectory(folder);PresentationBridge presentation(r);
  r.game.returnToTitle();replay(r,row.at("trace").get<std::string>().c_str(),row.value("limit",0));need(r.game.mode()==ApplicationMode::Playing&&r.game.mapId()==151,"08 stage replay did not reach ordinary point");source=folder/row.at("output").get<std::string>();const auto disk=decodeSave(c,read(source.c_str()));GameSession committed(c.items,disk.session,c.facts);finishSaveContinuation(committed,disk);need(durableEqual(committed.exportState(),r.game.session().exportState()),"08 ordinary disk changed durable actual state");need(r.game.session().saveCount()==row.at("save_count"),"08 replay missed actual ordinary save");summary(r,folder);std::cout<<"08 cumulative07 stage="<<row.at("name")<<" PASS source="<<source<<'\n';
 }
}

