int main(int argc,char** argv){try{std::cout.setf(std::ios::unitbuf);need(argc==8,"08 package actual-save isolated-root boss|replay|replay03|replay04|grab-success|grab-failure|load|boundary trace limit outputSlot");auto c=loadCombatContent(argv[1]);const bool cycle=std::string(argv[4]).starts_with("cycle-");need(c.compatibility==(cycle?"post-f5-g7-normal-7":"post-f5-g3-normal-7"),"08 wrong cumulative package");if(std::string(argv[4])=="loads"){std::filesystem::create_directories(argv[3]);loadBatch(c,argv[3],argv[5]);return 0;}if(std::string(argv[4])=="plan"){std::filesystem::create_directories(argv[3]);plan(c,argv[3],argv[5]);return 0;}const auto source=read(argv[2]);const auto saved=decodeSave(c,source);if(cycle){need(saved.session.worldValues.at(c.facts.variables.at(635))==1,"Cycle G3 requires an actual completed first-cycle source");}const auto root=std::filesystem::path(argv[3]);std::filesystem::create_directories(root);std::ofstream(root/"slot-01.json")<<source;std::ofstream(root/"slot-02.json")<<source;const std::string mode=cycle?std::string(argv[4]).substr(6):argv[4];auto cycleRandom=std::make_shared<std::mt19937>(19202026);auto random=[&,cycleRandom](int low,int high){if(cycle&&(mode=="boss"||mode=="boss-win")){return std::uniform_int_distribution<int>(low,high)(*cycleRandom);}if(mode=="replay03"&&low==1&&high==2){return 1;}if((mode=="replay04"||mode=="natural04")&&(low==0&&high==400)){return 0;}if((mode=="replay04"||mode=="natural04")&&low==0&&high==10){return 6;}if(mode.starts_with("grab-")&&low==0&&high==4){return 2;}return safe(low,high);};G2NaturalDriver r(c,root,"public-inputs.jsonl",random);r.game.configureSaveDirectory(root);PresentationBridge presentation(r);
 if(cycle&&(mode=="boss"||mode=="boss-win")){std::ofstream(root/"random-source.json")<<Json{{"kind","fixed-seed-uniform-native-range"},{"seed",19202026},{"seed_selected_before_run",true},{"pressure_sample_reused",false},{"runtime_state_injection",false}}.dump(2)<<'\n';}if(mode=="diagnose"){need(cycle,"Diagnosis requires explicit actual cycle source");auto after=r.afterTick;int rounds=-1,damage=-1,hp=-1;std::ofstream observations(root/"geometry-observations.jsonl");r.afterTick=[&]{after();if(!r.game.hasGame()||r.game.mapId()!=165||r.game.foreground()!=ForegroundKind::None){return;}const auto& g=r.game;const auto& s=g.session();const auto player=g.world().player().motion;const int current=s.magazine(s.equipped(1));if(current!=rounds||s.variable(89)!=damage||s.hp()!=hp||r.ticks%30==0){Json row{{"step",r.ticks},{"hp",s.hp()},{"weapon",s.equipped(1)},{"rounds",current},{"raised",g.raised()},{"facing",int(player.facing())},{"player_tile",{player.tile().x,player.tile().y}},{"player_position",{player.position().x,player.position().y}},{"camera",{g.cameraCenter().x,g.cameraCenter().y}},{"eye",{s.variable(83),s.variable(84)}},{"eye_velocity",{s.variable(81),s.variable(82)}},{"eye_damage",s.variable(89)},{"registration",s.variable(90)},{"body_damage",s.variable(103)},{"open",s.variable(105)}};observations<<row.dump()<<'\n';std::cout<<"Geometry "<<row.dump()<<'\n';}rounds=current;damage=s.variable(89);hp=s.hp();};r.game.returnToTitle();replay(r,argv[5],std::stoi(argv[6]));need(r.game.session().saveCount()==saved.session.saveCount,"Read-only diagnosis advanced saves");}else if(mode=="boss"||mode=="boss-win"){boss(r,cycle,mode!="boss-win");}else if(mode=="natural04"){r.load();natural04(r,false,cycle);}else if(mode.starts_with("replay")){replay(r,argv[5],std::stoi(argv[6]));need(r.game.mode()==ApplicationMode::Playing&&r.game.mapId()==151,"08 successful prefix did not end at ordinary point");const auto disk=decodeSave(c,read((root/("slot-0"+std::string(argv[7])+".json")).c_str()));GameSession committed(c.items,disk.session,c.facts);finishSaveContinuation(committed,disk);need(durableEqual(committed.exportState(),r.game.session().exportState()),"08 final ordinary disk differs from durable actual Session");}
 else if(mode=="grab-success"||mode=="grab-failure"){grabbed(r,mode=="grab-success");}else if(mode=="boundary"){boundary(r);}else if(mode=="load"){r.load();const auto actual=r.game.session().exportState();const auto expected=prepareRestore(c,saved).session->exportState();need(actual.inventory==expected.inventory&&actual.magazines==expected.magazines&&actual.worldFlags==expected.worldFlags&&actual.worldValues==expected.worldValues&&actual.conditions==expected.conditions&&actual.hp==expected.hp,"08 independent Load changed durable resources/state");std::cout<<"08 actual independent process Load complete state PASS\n";}else{throw std::runtime_error("Unknown08 mode");}summary(r,root);return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
